check('Architecture annotations fill unknown uses while explicit primary and secondary source uses retain priority',()=>{const b=fixture(square,{properties:{usage_1:'Indifférencié',architectureUse:'Hôpital'}});assert.equal(G.programTheme(b.use),'medical');assert.equal(G.programTheme(fixture(square,{properties:{usage_1:'Indifférencié',nature:'Industriel, agricole ou commercial',architectureUse:'Hôpital'}}).use),'medical');assert.equal(G.programTheme(fixture(square,{properties:{usage_1:'Indifférencié',nature:'Silo',architectureUse:'Hôpital'}}).use),'industrial');assert.equal(G.programTheme(fixture(square,{properties:{usage_1:'Indifférencié',nature:'Indifférenciée',architectureUse:'Religieux'}}).use),'civic');assert.equal(G.programTheme(fixture(square,{properties:{usage_1:'Indifférencié',usage_2:'Commercial et services',architectureUse:'Église'}}).use),'commercial');assert.equal(G.programTheme(fixture(square,{properties:{usage_1:'Industriel',architectureUse:'Église'}}).use),'industrial');});
for(const[use,kind,required]of[['Sportif','sports',['bench','wardrobe','washbasin']],['Annexe','annex',['crate','shelf','workbench']],['Bureau','office',['desk','archive','bench']]])check('The '+use+' programme keeps its source function instead of inventing bedrooms',()=>{const l=G.layout(fixture(largeSquare,{properties:{usage_1:use}}));assert.equal(l.theme,kind);for(const type of required)assert.ok(l.furniture.some(f=>f.kind===type));assert.ok(l.furniture.every(f=>!['bed','kitchen','sofa'].includes(f.kind)));assert.equal(l.programCoverage.furnishingOmissions.length,0);});
for(const[w,d,count,complete]of[[4,6,4,false],[5,8,5,false],[6,9,6,true]])check('A '+w*d+' square metre dwelling receives privacy, distinct essential functions and honest omissions',()=>{const b=fixture([[[0,0],[w,0],[w,d],[0,d]]],{height:3,levels:1}),l=G.layout(b,0,[-w/2+1,-d/2+1]);assert.ok(l.rooms.some(r=>r.type==='sanitary'&&r.coverage==='enclosed-room'));for(const kind of['sanitary',...(w*d>=35?['bed']:['sofa']),'kitchen','wardrobe'])assert.ok(l.furniture.some(f=>f.kind===kind),kind);assert.ok(new Set(l.furniture.map(f=>f.kind)).size>=count);assert.equal(l.programCoverage.allRequestedFunctionsPlaced,complete);assert.equal(l.programCoverage.footprintArea,w*d);const r=reachable(l);assert.equal(r.reached,r.all,JSON.stringify(r.unreached.slice(0,3)));});
check('Every invented room is enclosed by full partitions apart from its one metric doorway',()=>{const l=G.layout(fixture(courtyard)),coverage=l.programCoverage;assert.ok(l.rooms.length>0);for(const r of l.rooms){let perimeter=0,partitionLength=0;for(let i=0;i<4;i++){const a=r.ring[i],b=r.ring[i+1];perimeter+=Math.hypot(a[0]-b[0],a[1]-b[1]);for(const w of l.walls)if(G.segmentDistance(w.a,a,b)<1e-6&&G.segmentDistance(w.b,a,b)<1e-6)partitionLength+=Math.hypot(w.a[0]-w.b[0],w.a[1]-w.b[1]);}assert.ok(Math.abs(perimeter-partitionLength-r.door.width)<1e-6);assert.equal(r.door.width,1.2);assert.ok(G.canTravel(l,r.door.inside,r.door.outside,.38));for(const p of r.ring)assert.ok(G.clearance(l.rings,...p)>=.18);assert.ok(!l.furniture.some(f=>G.furnitureBlocked(f,...r.door.center,.38)));}assert.ok(Math.abs(coverage.enclosedRoomArea+coverage.openSourceArea-364)<1e-6);assert.equal(l.openSpace.area,coverage.openSourceArea);assert.deepEqual(l.openSpace.rings,l.rings);assert.deepEqual(l.openSpace.excludedRooms,l.rooms.map(r=>r.id));assert.equal(coverage.navigation.newUnreachableCells,0);});
check('Furniture access remains on the same side of every partition and within its assigned room',()=>{const l=G.layout(fixture());for(const f of l.furniture){assert.ok(G.canTravel(l,f.pos,f.approach,.04));assert.ok(G.walkable(l,...f.approach,.38));assert.ok(!l.furniture.some(a=>G.furnitureBlocked(a,...f.approach,.38)));if(f.roomId){const room=l.rooms.find(r=>r.id===f.roomId);assert.ok(G.clearance([room.ring],...f.approach)>=.38);for(const p of f.ring)assert.ok(G.clearance([room.ring],...p)>=.11);}}});
check('A rotated footprint keeps its metric rooms and oriented furniture solids inside the true outline',()=>{const angle=Math.PI/6,c=Math.cos(angle),s=Math.sin(angle),rotate=p=>[c*p[0]-s*p[1],s*p[0]+c*p[1]],rings=[[[-10,-8],[10,-8],[10,8],[-10,8]].map(rotate)],l=G.layout(fixture(rings));assert.deepEqual(l.rings,fixture(rings).rings);assert.ok(l.rooms.length>=3);assert.ok(l.furniture.length>=6);assert.ok(l.furniture.some(f=>Math.abs(Math.sin(f.rotation))>.4));for(const f of l.furniture){assert.equal(f.ring.length,5);assert.deepEqual(f.localSize,G.FURNITURE[f.kind].size);for(const p of f.ring)assert.ok(G.clearance(l.rings,...p)>=.13);}const r=reachable(l,.1);assert.equal(r.reached,r.all,JSON.stringify(r.unreached.slice(0,3)));});
check('A tiny source courtyard is excluded from rooms and furniture even between sample points',()=>{const hole=[[5.13,5.17],[5.13,5.32],[5.28,5.32],[5.28,5.17]],b=fixture([square[0],hole]),l=G.layout(b);const p=[5.18-b.origin[0],5.22-b.origin[2]];assert.ok(l.rooms.every(r=>!G.inside([r.ring],...p)));assert.ok(l.furniture.every(f=>!G.inside([G.furnitureRing(f)],...p)));});
check('A documented high nave is accepted at its measured height without inventing intermediate levels',()=>{const b=fixture(square,{height:19.4,levels:1}),d=documentFixture(b);d.levels[0].height=19.4;const l=G.layout(b,0,null,d);assert.equal(l.height,19.4);assert.equal(l.levels,1);assert.deepEqual(l.walls,G.document(d,b).levels[0].walls);assert.equal(l.roomsBasis,'documented');});
check('Large and complex programmes publish their bounded proof and omissions instead of claiming an exhaustive survey',()=>{const l=G.layout(fixture([[[0,0],[1000,0],[1000,400],[0,400]]],{height:900,levels:200}),199,[-498,-198]),p=l.programCoverage;assert.ok(p.navigation.sampledCells<=G.PLAN_BUDGET.gridCells);assert.ok(p.navigationChecks<=G.PLAN_BUDGET.navigationChecks);assert.ok(l.rooms.length<=G.PLAN_BUDGET.rooms);assert.ok(l.furniture.length<=G.PLAN_BUDGET.furniture);assert.equal(p.roomsLimited,true);assert.ok(p.roomOmissions.length>0);assert.equal(p.provenance,'invented');});

check('An unproven narrow source connection keeps its whole original volume open instead of being partitioned shut',()=>{const rings=[[[0,0],[5.4,0],[5.4,1.55],[11.4,1.55],[11.4,0],[17.4,0],[17.4,6],[11.4,6],[11.4,2.45],[5.4,2.45],[5.4,6],[0,6]]],b=fixture(rings,{id:'review-neck-5.4',height:9,levels:3}),l=G.layout(b,0,[-7.7,-2]);assert.deepEqual(l.rings,b.rings);assert.equal(l.walls.length,0);assert.equal(l.furniture.length,0);assert.ok(l.programCoverage.navigation.sourceUnreachableCells>0);assert.ok(l.programCoverage.roomOmissions.every(r=>r.reason==='source-circulation-unproven'));assert.ok(l.programCoverage.furnishingOmissions.every(r=>r.reason==='source-circulation-unproven'));assert.ok(G.canTravel(l,[-4.7,-1],[4.3,-1],.38));assert.equal(l.programCoverage.completeInventedProgram,false);});
check('Furniture assigned to a concave documentary room cannot bridge its narrow internal notch',()=>{const b=fixture(square,{height:3,levels:1}),d=documentFixture(b);d.levels[0].height=3;d.levels[0].walls=[];d.levels[0].rooms=[{id:'u',use:'Chambre',ring:[[-3,-2],[3,-2],[3,2],[-2.05,2],[-2.05,-1.5],[-2.2,-1.5],[-2.2,2],[-3,2]]}];const l=G.layout(b,0,null,d);assert.deepEqual(l.rooms,G.document(d,b).levels[0].rooms);for(const f of l.furniture.filter(f=>f.roomId==='u')){const bb=G.bounds([f.ring]);for(let x=bb.minX+.01;x<bb.maxX;x+=.05)for(let z=bb.minZ+.01;z<bb.maxZ;z+=.05)assert.ok(G.inside([l.rooms[0].ring],x,z));assert.ok(G.inside([l.rooms[0].ring],...f.pos));}});

