check('The real29m² curved volume gains essential equipment and keeps free boundary pockets connected',()=>{const source=JSON.parse(JSON.stringify(actualSmallCurvedSource)),before=JSON.parse(JSON.stringify(source)),b=G.building(F.describe(source)),entry=[1.9686079072034772,.7890987265345757],legacy={...b,layoutVersion:2},old=G.layout(legacy,0,entry),l=G.layout(b,0,entry);assert.deepEqual(source,before);assert.deepEqual(l.rings,b.rings);assert.equal(l.layoutVersion,5);assert.ok(!old.furniture.some(f=>f.kind==='bed'));for(const kind of['bed','kitchen','sanitary','wardrobe','sofa'])assert.ok(l.furniture.some(f=>f.kind===kind),kind);assert.equal(l.programCoverage.equipmentScale,'single-bed-and-separate-wc');assert.equal(l.programCoverage.enclosedRooms,0);assert.equal(l.programCoverage.enclosedRoomArea,0);assert.ok(l.programCoverage.roomOmissions.some(r=>r.type==='sanitary'&&r.reason==='no-contained-connected-room'));assert.deepEqual(l.programCoverage.furnishingOmissions.map(f=>f.kind),['dining']);assert.ok(l.programCoverage.boundaryAccessSamples>0&&l.programCoverage.boundaryAccessSamples<=l.programCoverage.budgets.boundaryAccessProbes);for(const kind of['bed','sanitary']){const f=l.furniture.find(f=>f.kind===kind);assert.equal(f.variant,'compact');assert.deepEqual(f.localSize,G.COMPACT_FURNITURE[kind].size);assert.ok(G.walkable(l,...f.approach,.38));assert.ok(!l.furniture.some(v=>G.furnitureBlocked(v,...f.approach,.38)));}const r=reachable(l,.1);assert.equal(r.reached,r.all,JSON.stringify(r.unreached.slice(0,5)));});
check('Compact furniture renders within its declared physical dimensions instead of shrinking the actor',()=>{for(const kind of['bed','sanitary']){const f={kind,variant:'compact'},d=G.furnitureDefinition(f),parts=G.furnitureModel(f);assert.ok(parts.length>0);for(const part of parts){assert.ok(Math.abs(part.pos[0])+part.size[0]/2<=d.size[0]/2+1e-7);assert.ok(Math.abs(part.pos[2])+part.size[2]/2<=d.size[1]/2+1e-7);assert.ok(part.pos[1]+part.size[1]/2<=d.height+1e-7);assert.ok(part.pos[1]-part.size[1]/2>=-1e-7);}}});
check('Compact variants never replace documentary room geometry or equipment programmes',()=>{const b=fixture([[[0,0],[6,0],[6,8],[0,8]]],{height:4,levels:1}),d={schemaVersion:1,frame:'building-local-metre',buildingId:b.id,source:documentFixture(b).source,levels:[{level:0,elevation:0,height:4,walls:[],rooms:[{id:'room',use:'Chambre',ring:[[-3,-4],[3,-4],[3,4],[-3,4],[-3,-4]]}]}]},checked=G.document(d,b),l=G.layout(b,0,null,d);assert.deepEqual(l.walls,checked.levels[0].walls);assert.deepEqual(l.rooms,checked.levels[0].rooms);assert.equal(l.programCoverage.equipmentScale,'standard');assert.ok(l.furniture.every(f=>!f.variant));});


check('Explicit imported school and health attributes select their own programmes with source provenance',()=>{
 for(const[properties,kind,field]of[[{building:'yes',amenity:'school'},'education','amenity'],[{building:'school'},'education','building'],[{'building:use':'Enseignement'},'education','building:use'],[{usage_1:'École'},'education','usage_1'],[{amenity:'hospital'},'medical','amenity'],[{amenity:'doctors'},'medical','amenity'],[{shop:'bakery'},'commercial','shop'],[{shop:'clothes'},'commercial','shop'],[{shop:'hairdresser'},'commercial','shop'],[{building:'office'},'office','building']]){const b=fixture(square,{properties});assert.equal(b.programmeUse.kind,kind);assert.equal(b.programmeUse.field,field);assert.equal(b.programmeUse.basis,'source-attribute');assert.deepEqual(G.validateBuilding(JSON.parse(JSON.stringify(b))).programmeUse,b.programmeUse);}
});
check('New explicit warehouse and greenhouse imports preserve a single unknown hall while declared levels prevail',()=>{for(const building of['warehouse','greenhouse','farm','workshop']){const b=fixture(square,{height:18,levels:null,properties:{building}});assert.equal(b.programmeUse.kind,'industrial');assert.equal(b.levels,1);assert.equal(b.levelHeight,18);const declared=fixture(square,{height:18,levels:3,properties:{building,'building:levels':3}});assert.equal(declared.levels,3);assert.equal(declared.levelHeight,6);assert.equal(declared.levelsBasis,'building:levels');}});
check('A name cannot turn unknown or commercial IGN use into a supposedly measured school or hospital',()=>{
 for(const name of['École élémentaire fixture','Hôpital fictif']){const unknown=fixture(square,{properties:{name,usage_1:'Indifférencié',nature:'Indifférenciée'}});assert.equal(unknown.programmeUse.kind,'residential');assert.equal(unknown.programmeUse.basis,'invented-fallback');assert.equal(unknown.programmeUse.field,null);const commercial=fixture(square,{properties:{name,usage_1:'Commercial et services'}});assert.equal(commercial.programmeUse.kind,'commercial');assert.equal(commercial.programmeUse.value,'Commercial et services');}
 const annotated=fixture(square,{properties:{usage_1:'Indifférencié',architectureUse:'Enseignement'}});assert.equal(annotated.programmeUse.kind,'education');assert.equal(annotated.programmeUse.basis,'architecture-annotation');assert.equal(annotated.programmeUse.field,'architectureUse');assert.equal(fixture(square,{properties:{usage_1:'Industriel',architectureUse:'Hôpital'}}).programmeUse.kind,'industrial');
});
check('Saved programme metadata rejects a conflicting kind, value or unsupported source field',()=>{const b=fixture(square,{properties:{amenity:'school'}});for(const change of[{kind:'medical'},{value:'Hôpital',kind:'medical'},{field:'invented-survey'},{basis:'surveyed'},{value:'x'.repeat(161)}])assert.throws(()=>G.validateBuilding({...b,programmeUse:{...b.programmeUse,...change}}));const legacyFour={...b};delete legacyFour.programmeUse;assert.equal(G.validateBuilding(legacyFour).programmeUse.basis,'saved-use');});
check('A small shop prioritises actual sales equipment before adding support rooms',()=>{const b=fixture([[[0,0],[5,0],[5,5],[0,5]]],{height:4,levels:1,properties:{usage_1:'Commercial'}}),l=G.layout(b,0,[-1.5,-1.5]);for(const kind of['reception','checkout','shelf','bench','sanitary'])assert.ok(l.furniture.some(f=>f.kind===kind),kind);assert.equal(l.rooms.length,0);assert.equal(l.programCoverage.furnishingOmissions.length,0);assert.equal(l.programCoverage.useBasis.basis,'source-attribute');const r=reachable(l,.1);assert.equal(r.reached,r.all,JSON.stringify(r.unreached.slice(0,4)));});
check('A programme with omitted essential equipment cannot claim all equipment was placed',()=>{const l=G.layout(fixture([[[0,0],[2,0],[2,2],[0,2]]],{height:4,levels:1,properties:{usage_1:'Commercial'}}));assert.ok(l.programCoverage.furnishingOmissions.length>0);assert.equal(l.programCoverage.equipmentQuantities.length,0);assert.equal(l.programCoverage.allRequestedEquipmentPlaced,false);assert.equal(l.programCoverage.allRequestedFunctionsPlaced,false);assert.equal(l.programCoverage.completeInventedProgram,false);});
