check('An explicit school programme closes an accessible classroom and equips several pupil workstations',()=>{const b=fixture(square,{id:'programme-fixture',height:4,levels:1,properties:{usage_1:'Enseignement'}}),l=G.layout(b,0,[-9,-9]),room=l.rooms.find(r=>r.type==='classroom');assert.equal(l.theme,'education');assert.ok(room);assert.ok(Math.abs(G.area(room.ring))>=30-1e-7);for(const kind of['teaching_board','school_desk'])assert.ok(l.furniture.some(f=>f.kind===kind&&f.roomId===room.id));const count=l.programCoverage.equipmentQuantities.find(q=>q.roomId===room.id&&q.kind==='school_desk');assert.equal(count.requested,4);assert.equal(count.placed,4);assert.equal(count.complete,true);assert.equal(l.programCoverage.allRequestedEquipmentPlaced,true);assert.equal(l.programCoverage.furnishingOmissions.length,0);assert.ok(l.furniture.every(f=>!['bed','kitchen','sofa'].includes(f.kind)));const r=reachable(l);assert.equal(r.reached,r.all,JSON.stringify(r.unreached.slice(0,4)));});
